"""Canonical audited dashboard. Standard library only; legacy URLs remain usable."""
from pathlib import Path
from html import escape as e
import csv, json, os
R=Path(__file__).resolve().parent.parent
NBA='https://www.nba.com/stats/'
G=NBA+'help/glossary'
CAL='https://scikit-learn.org/stable/modules/calibration.html'
TIME='https://scikit-learn.org/stable/modules/generated/sklearn.model_selection.TimeSeriesSplit.html'
COR='https://docs.scipy.org/doc/scipy/reference/generated/scipy.stats.pearsonr.html'
REPO='https://github.com/sassnarep3-star/Own7'
nav=[('index.html','Overview'),('signals.html','Strategies'),('validation.html','Validation'),('correlation.html','Correlation'),('leaderboard.html','Leaderboard'),('findings.html','NBA data'),('sources.html','Sources'),('review.html','Flagged for Review')]
def table(headers,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+e(x)+'</th>' for x in headers+['Official / primary source'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in row[:-1])+'<td><a href="'+e(row[-1])+'">Source ↗</a></td></tr>' for row in rows)+'</tbody></table></div>'
def page(name,title,intro,body):
    links=''.join(f'<a class="{"active" if name==p else ""}" href="{p}">{label}</a>' for p,label in nav)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | OWN7</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="shell"><aside><a class="brand" href="index.html">OWN7 <small>NBA RESEARCH LAB</small></a><div class="side-label">RESEARCH WORKSPACE</div><nav aria-label="Main navigation">{links}</nav><div class="side-note">Evidence before action.<small>Audited 03 Nov 2026</small></div></aside><main><header>NBA / {e(title)} <span class="header-right">RESEARCH ONLY</span></header><div class="content"><div class="eyebrow">INDEPENDENT LINE ORIGINATION</div><h1>{e(title)}</h1><p class="intro">{e(intro)}</p>{body}<footer>OWN7 · Audit date 2026-11-03 · No betting recommendations. Luck cannot be eliminated. Blank cells mean unverified or not computed, never zero.</footer></div></main></div></body></html>'''
pages={}
pages['index.html']=page('index.html','A better line starts with evidence.','Executive summary · A source-linked foundation for NBA forecasting, not a claim of a profitable system.','''<div class="notice"><div><strong>No strategies have passed validation.</strong><br>No executable odds archive, fitted forecasts, backtest returns or measured betting correlations are available. Do not use this dashboard as live picks.</div></div><div class="metrics"><div class="metric"><span>APPROVED STRATEGIES</span><b>0</b><small>Repository audit count</small></div><div class="metric"><span>CANDIDATE STRATEGIES</span><b>8</b><small>Project proposals, not findings</small></div><div class="metric"><span>MEASURED CORRELATIONS</span><b>—</b><small>Paired observations needed</small></div></div><section><h2>Executive decision</h2><p>Develop independent distributions for game margin, game total and player outcomes. Freeze forecasts before observing odds, then compare to timestamped executable prices. Singles are the baseline; parlays and prop combos require joint-outcome models. No funding or real-money reward is authorized.</p>'''+table(['Finding','Action','Evidence status'],[
('Time-ordered data must not be trained on future observations.','Walk-forward validation grouped by game date; do not randomly split related legs.','Method verified in official software documentation; NBA implementation proposed',TIME),
('Aggregate probability scores combine reliability, resolution and uncertainty.','Report reliability plots plus log loss and Brier score.','Method verified; no project scores computed',CAL),
('NBA standings were readable during this audit.','Publish the 30-row snapshot separately; standings do not establish betting skill.','Official snapshot checked 2026-11-03','https://www.nba.com/standings'),
('Earlier dashboards disagreed about data verification.','Consolidate navigation; blank unsupported season statistics and retire conflicting pages.','Repository audit finding',REPO),
('No validated strategy, betting edge or measured correlation is established.','Keep results blank and reward eligibility closed.','Repository state, not evidence that a strategy can never work',REPO)
])+'''</section><section><h2>What “skill based” means here</h2><p>Luck cannot be removed. The proposed competition rewards repeatable out-of-sample probability quality and positive net returns with uncertainty controls, rather than streaks. A historical edge can fail in a new market regime. The evidence necessary to distinguish skill from luck is not yet present.</p><a class="button" href="signals.html">Explore candidate strategies →</a></section>''')
strategies=[('S01','Single / moneyline','Regularized team strength with opponent adjustment','Rolling game history; home/away; pregame availability','Home-win probability; benchmark against intercept-only and no-vig market'),('S02','Single / spread','Team attack and defense with rest adjustment','Pregame schedule; score margins; availability','Margin distribution; fair home spread = negative expected home margin'),('S03','Single / total','Possessions × opponent-adjusted efficiency','Pace; offensive and defensive ratings; rest','Total distribution; fair total = predictive median for symmetric half-point market'),('S04','Player / points','Minutes uncertainty × scoring opportunity','Timestamped lineup status; past minutes and usage','Full points distribution, not a deterministic over'),('S05','Player / rebounds','Minutes and rebound opportunity model','Past minutes; shot mix; opponent rebounding','Rebound count distribution and calibrated threshold probabilities'),('S06','Multi-game parlay','Combine eligible singles only after dependence checks','Same-time executable combined quote; aligned outcomes','Estimate all-legs-win probability; independence is not assumed'),('S07','Same-game combo','Team total with player points','Joint game/player simulation; overtime and lineup scenarios','Joint win probability; shared pace and minutes risks'),('S08','Same-player combo','Points with assists / rebounds','Aligned game logs; roles; minutes; offered thresholds','Joint tail probability; test conditional dependence')]
pages['signals.html']=page('signals.html','Strategy register','Eight untested research proposals. Linked NBA sources describe potential inputs, not endorsements of these strategies.',table(['ID','Category','Hypothesis (project design)','Required inputs','Origination output'],[(*s,G) for s in strategies])+'''<section><h2>Pricing specification · project design</h2><p>For a no-push binary event with estimated probability p: fair decimal odds = 1/p; net expected value per unit = p × offered decimal odds − 1. These are mathematical definitions, not estimated NBA prices. With pushes: net EV = p(win) × (odds − 1) − p(loss); pushes return stake. For two-way, no-push markets, proportional no-vig baseline qᵢ = (1/dᵢ) / Σ(1/dⱼ); this is a chosen normalization, not proof of true market probabilities.</p><p>For parlays use P(all legs win), not a product of marginal probabilities unless independence is justified. Pairwise correlation alone does not identify a multi-leg joint tail. Settle voids, pushes, overtime and DNPs according to the exact operator rules before evaluation. No operator quotes or settlement rules have been verified here.</p></section>''')
gates=[('G01','Provenance','Store official URL, retrieval UTC, season, game/player IDs, raw response hash, schema and corrections. Reject duplicate or incomplete records.'),('G02','As-of integrity','Features and availability known strictly before prediction cutoff; freeze predictions before odds comparison. Keep final-game statistics out of inputs.'),('G03','Locked test','Pre-register features, all attempted variants and disjoint train/tune/test date windows; no tuning after seeing test. Group related games/legs by date.'),('G04','Calibration','Improve held-out log loss over intercept and de-vigged market; report Brier and reliability by probability band. No aggregate score substitutes for calibration.'),('G05','Uncertainty and selection','Project rule: game-date block bootstrap, 95% interval for net ROI lower bound above zero; multiplicity-adjusted tests at 5% across all trials. Fix block length and minimum detectable effect before tests; reject underpowered entries.'),('G06','Execution realism','Timestamp actual offered prices and limits; include vig, rejected orders, slippage, void/push rules. Compare like-for-like closing lines as diagnostics, not proof of skill.'),('G07','Dependence','Estimate paired residual and binary-leg correlations with sample sizes and intervals; validate joint probability calibration. Reject combos without enough aligned observations.'),('G08','Robustness','Require positive direction in separate time blocks and predeclared forward-paper window; stress lineups, seasons and worse prices. Duration and power must be frozen before evaluation.'),('G09','Governance','Reproducible code and seed, immutable entry IDs, disqualification for leakage, legal/operator availability checked, no real stakes or payouts without approved funding and limits.')]
pages['validation.html']=page('validation.html','Validation gates','All nine gates are proposed project policies. No candidate has been evaluated or passed.',table(['Gate','Purpose','Pass rule (project design)','Current status'],[(a,b,c,'Blocked / not evaluated', TIME if a in ('G02','G03') else CAL if a=='G04' else COR if a=='G07' else REPO+'/blob/main/scripts/build_dashboard.py') for a,b,c in gates])+'''<p>Thresholds above are design choices, not externally verified guarantees. A gate is NOT passed by having a source link. Minimum sample size is deliberately not guessed: it needs an effect-size and dependence-aware power calculation before the first evaluation.</p>''')
corr=list(csv.DictReader((R/'data/team-correlations-2025-26.csv').open()))
corr_html='<section><h2>Team-level correlations (2025-26, computed)</h2><p>Pearson r across the 30 team-season rows of the verified NBA.com team table. Descriptive context only: these are not bet-leg correlations and do not give the joint probability of any two bets. Script: scripts/compute_team_correlations.py.</p>'+table(['Pair (team-season)','n teams','r','r squared','Status'],[(c['Pair'],c['n_teams'],c['r'],c['r_squared'],'Computed from verified inputs; descriptive, not bet-leg',c['Source']) for c in corr])+'</section>'
pages['correlation.html']=page('correlation.html','Correlation & combinations','No bet-leg coefficient has been computed (no paired game data). Team-season descriptive correlations are shown below. A missing value is not an estimate of zero.',table(['Pair','Proposed measurement','Coefficient','N','Status'],[(pair,method,'','','Unverified / paired game data absent',COR) for pair,method in [('Points / assists, same player','Pearson and Spearman; condition on pregame role and projected minutes'),('Teammate points / points','Paired residuals after shared pace and role adjustment'),('Team total / win','Point-biserial; separate game-level and market-threshold outcomes'),('Over points / over assists','Binary outcome correlation at timestamped offered thresholds'),('Different-game legs','Aligned date blocks; test common exposures rather than assume independence')]])+corr_html+'''<section><h2>Estimation protocol · project design</h2><p>Join by official game ID and player ID; exclude incomplete pairs and report exclusions. Report season, cutoff, N, coefficient and game-date block-bootstrap 95% interval. Constant series have undefined correlation; leave blank. Pearson measures linear association, not causation or independence. Spearman is a sensitivity check. Never substitute a logistic regression coefficient for a correlation.</p><p>For two no-push binary legs, the identity P(A∩B) = pA pB + ρ √[pA(1−pA)pB(1−pB)] only works when ρ refers to those exact binary events. It does not allow plugging in raw player-stat correlation. Estimated joint probabilities must satisfy max(0,pA+pB−1) ≤ P(A∩B) ≤ min(pA,pB). For three or more legs, model and validate the full joint distribution.</p></section>''')
pages['leaderboard.html']=page('leaderboard.html','Evidence over hot streaks.','Proposed competition rules. No real-money reward pool, validated entrants, scores or winners.',table(['Entry','Eligible','Sample','Log loss','Net ROI','Reward status'],[('No qualifying entries','No','','','','Not funded / not awarded',REPO)])+'''<section><h2>Leaderboard charter · project design</h2><p>Separate singles, multi-game parlays, individual props and same-game combos. Freeze each submission, date cutoff, code hash and prediction log; all nine gates must pass. Rank qualifying entries by held-out log-loss improvement against a common benchmark within the same market cohort; tie-break by net ROI lower confidence bound, then lower drawdown. Do not compare raw log loss across unrelated event types.</p><p>Publish total bets, effective game clusters, exposure, ROI interval, closing-line diagnostics, calibration and rejected trades. Keep all attempted variants in the trial registry, including failures. The proposed reward is a non-cash research badge after an independent forward-paper replication. Cash amount and funding remain blank; nobody is promised a payout. No winner can be selected from the current evidence.</p></section>''')
teams=list(csv.DictReader((R/'data/teams-2025-26.csv').open()))
players=list(csv.DictReader((R/'data/players-2025-26-top15.csv').open()))
rows=list(csv.DictReader((R/'data/standings-2026-27.csv').open()))
team_tbl=table(['Rank','Team','Conf','GP','W','L','WIN%','PTS','FG%','3P%','REB','AST','TOV','+/-'],[(x['Rank'],x['Team'],x['Conference'],x['GP'],x['W'],x['L'],x['WIN%'],x['PTS'],x['FG%'],x['3P%'],x['REB'],x['AST'],x['TOV'],x['+/-'],x['Source']) for x in teams])
player_tbl=table(['Rank','Player','Team','Age','GP','MIN','PTS','REB','AST','FG%','3P%','FT%'],[(x['Rank'],x['Player'],x['Team'],x['Age'],x['GP'],x['MIN'],x['PTS'],x['REB'],x['AST'],x['FG%'],x['3P%'],x['FT%'],x['Source']) for x in players])
standings_tbl=table(['Conference','Rank','Team','W','L','WIN%','Notes'],[(r['Conference'],r['Rank'],r['Team'],r['W'],r['L'],r['WIN%'],r['Notes'],r['Source']) for r in rows])
pages['findings.html']=page('findings.html','Official NBA data','Every value below was re-read from the official NBA.com page and matched by script on 2026-11-03 (scripts/verify_official_snapshots.py). Each row links to its source. Blank means unverified.','<section><h2>2025-26 team statistics (30 teams, regular season)</h2>'+team_tbl+'<p>Values match the official table on every mapped column. Columns not shown here (MIN, FGM, FGA, 3PM, 3PA, FTM, FTA, BLKA) are in data/teams-2025-26.csv only where mapped.</p></section><section><h2>2025-26 player statistics (top 15 by points per game)</h2>'+player_tbl+'</section><section><h2>2026-27 standings (in progress; small sample)</h2>'+standings_tbl+'<p>Games played (W+L) range from 5 to 8 per team, so this is a small sample and context only, never a standalone signal. Early-season records are not enough to establish betting skill. No game-level paired data or odds archive exists for a valid strategy test.</p></section>')
sources=[('NBA standings','Both chunks read; 30 team rows compared to CSV including W/L, percentages, records and streaks','Verified snapshot; dynamic page can change','https://www.nba.com/standings'),('NBA players traditional, 2025-26 per game','Ranks 1–15 read from the page; 15 rows (25 columns) matched by script on 2026-11-03','Verified snapshot; data/official-snapshots/players-2025-26-top15.txt','https://www.nba.com/stats/players/traditional?Season=2025-26&SeasonType=Regular%20Season&PerMode=PerGame'),('NBA teams traditional, 2025-26','All 5 chunks read; 30 rows (18 mapped columns) matched by script on 2026-11-03','Verified snapshot; data/official-snapshots/teams-2025-26.txt','https://www.nba.com/stats/teams/traditional?Season=2025-26&SeasonType=Regular%20Season'),('NBA glossary','USG% definition checked: percentage of team plays used while on floor','Definition verified; proposed feature is not a proven edge',G),('scikit-learn calibration','Read proper-score decomposition and reliability curve explanation','Official software documentation checked',CAL),('scikit-learn TimeSeriesSplit','Read future-to-past leakage warning and equally-spaced-samples caveat','Use NBA calendar blocks, not blindly equal row counts',TIME),('SciPy pearsonr','Read API description identifying Pearson coefficient and non-correlation test','Official software documentation checked; no NBA calculation',COR),('Own7 repository','Inspected tracked HTML, JSON, CSV, docs, scripts, workflows and coordination history','Primary authority for project policies only, not NBA facts',REPO)]
pages['sources.html']=page('sources.html','Source register','Verification means checking the stated claim, not merely recognizing an official domain. Audit date: 2026-11-03.',table(['Primary source','Scope actually read','Limits'],sources)+'''<p>Software documentation is authoritative for its methods, not for NBA betting profitability. Project links identify original design decisions. NBA source links identify data provenance; they do not validate a proposed model. External reachability was checked for the sources listed above, not every historical link in the repository.</p>''')
flags=[('F01','Conflicting old verification claims','Earlier pages asserted both verified season stats and no verified numbers. Canonical site supersedes them; old URLs now link here.',REPO),('F02','2025–26 team and player values (re-verified; reversed a prior blanking)','Re-read from the official nba.com 2025-26 team and player pages on 2026-11-03: 30 team rows and 15 player rows matched by script to transcribed snapshots (data/official-snapshots/). Values restored from that evidence. Owner: please confirm.',NBA),('F10','2026-27 standings note says ~8 games','Games played (W+L) range 5 to 8 per team; Phoenix (1-4) has 5 games and different note wording. Values match the official standings page.','https://www.nba.com/standings'),('F11','Team-level correlations are season cross-sections','Pearson r across 30 team-season rows (e.g. Win% vs +/- r = 0.973). Descriptive only; these are not bet-leg correlations and must not be used to price parlays.','https://www.nba.com/stats/teams/traditional?Season=2025-26&SeasonType=Regular%20Season'),('F12','Executive summary leaders corrected in superseded copy','Earlier copy named Miami as highest PPG and Denver as highest FG%. Official: Denver 122.1 PPG (Miami 120.9 second); Lakers 50.2 FG% (Denver 49.6 second). The superseded document is kept for history only.','https://www.nba.com/stats/teams/traditional?Season=2025-26&SeasonType=Regular%20Season'),('F13','Cross-game correlation cell','Earlier correlation register showed an assumed 0. Changed to blank: no independence is assumed without a stated, measured basis.',COR),('F14','Team rank column corrected (Utah 27 -> 26)','Independent re-read of the official NBA.com 2025-26 team table on 2026-11-04 showed Utah Jazz ranked 26 (tied with Sacramento), not 27 as previously published. CSV, snapshot and site corrected; Rank is now covered by scripts/verify_official_snapshots.py. First detected by session b11f3baa, confirmed and fixed by session 6fe08d51.','https://www.nba.com/stats/teams/traditional?Season=2025-26&SeasonType=Regular%20Season'),('F03','Betting prices and settlement rules','No timestamped executable quotes, operator archive or confirmed settlement specification. Lines, EV, ROI and CLV remain blank.',NBA),('F04','Correlation and skill','No aligned game-level observations, fitted models or forward results. No correlation coefficient or claim of skill established.',COR),('F05','Alberta jurisdiction and helplines','Inherited Alberta rules and phone numbers not independently verified; not assumed applicable to the user. Numeric details blanked in legacy JSON.',REPO),('F06','Reported 2026 NBA restrictions','Media-only claims not confirmed by an official primary document; no restriction treated as fact. Check market-specific legal rules before use.', 'https://www.nba.com/news'),('F07','Rewards and license','No funded cash reward pool or license file found. Proposed badge only; no payout or reuse license implied.',REPO),('F08','Verification scope','Static tests check structure and policy invariants, not scientific truth. Historical raw numeric values remain in Git history only; audit does not certify every prior narrative.',REPO),('F09','Automation limits','Static Pages cannot collect changing authenticated odds by itself. This session produced an auditable research specification, not an operating sportsbook or live forecast feed.',REPO)]
pages['review.html']=page('review.html','Flagged for Review','Non-blocking irregularities, missing evidence and unresolved research tasks. No manual input is required to read the site.',table(['ID','Item','Finding / disposition'],flags))
# Preserve old URLs, not contradictory content. Earlier versions remain in Git history.
for old in list((R/'pages').glob('*.html'))+list((R/'verified').glob('*.html')):
    target=os.path.relpath(R/'index.html',old.parent)
    old.write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Superseded research view</title><h1>This research view has been superseded</h1><p>Earlier verification claims were inconsistent. Use the consolidated audited dashboard.</p><a href="{target}">Open current dashboard</a></html>')
for name,content in pages.items(): (R/name).write_text(content)
print('Built',len(pages),'canonical pages; legacy URLs retained as superseded notices.')
